const cov = JSON.parse(require('fs').readFileSync('/var/tmp/loop-bench/runs/1642417e449d/ci-7/coverage/coverage-final.json', 'utf8'));
const thresholds = {
  'src/orchestration/': {statements: 88.3, branches: 80.85, functions: 92, lines: 87.91},
  'src/orchestration/tools/': {statements: 66.66, branches: 56.25, functions: 71.42, lines: 70.83},
  'src/infrastructure/stores/': {statements: 100, branches: 100, functions: 100, lines: 100},
  'src/providers/vertex/': {statements: 87.95, branches: 74.64, functions: 93.33, lines: 91.78},
  'src/providers/mock/': {statements: 100, branches: 78.57, functions: 100, lines: 100},
  global: {statements: 71.48, branches: 64.82, functions: 68.57, lines: 71.9},
};

function calc(filterFn) {
  let sTotal = 0, sCovered = 0;
  let bTotal = 0, bCovered = 0;
  let fTotal = 0, fCovered = 0;
  for (const [file, data] of Object.entries(cov)) {
    const rel = file.replace(/.*\/ci-7\//, '');
    if (!filterFn(rel)) continue;
    const s = Object.values(data.s);
    const b = Object.values(data.b).flat();
    const f = Object.values(data.f);
    sTotal += s.length; sCovered += s.filter(x => x > 0).length;
    bTotal += b.length; bCovered += b.filter(x => x > 0).length;
    fTotal += f.length; fCovered += f.filter(x => x > 0).length;
  }
  return {
    statements: (sCovered / sTotal * 100).toFixed(2),
    branches: (bCovered / (bTotal || 1) * 100).toFixed(2),
    functions: (fCovered / fTotal * 100).toFixed(2)
  };
}

console.log('src/orchestration/tools/:', calc(f => f.startsWith('src/orchestration/tools/')));
console.log('src/orchestration/:', calc(f => f.startsWith('src/orchestration/') && !f.startsWith('src/orchestration/tools/')));
console.log('src/infrastructure/stores/:', calc(f => f.startsWith('src/infrastructure/stores/')));
console.log('src/providers/vertex/:', calc(f => f.startsWith('src/providers/vertex/')));
console.log('src/providers/mock/:', calc(f => f.startsWith('src/providers/mock/')));
console.log('global (all files not in named paths):', calc(f => 
  !f.startsWith('src/orchestration/') &&
  !f.startsWith('src/infrastructure/stores/') &&
  !f.startsWith('src/providers/vertex/') &&
  !f.startsWith('src/providers/mock/')
));
